"use client"

import { cn } from "@/lib/utils"

const DEFAULT_EMOJIS = ["😀", "😂", "😍", "👍", "🙏", "🔥", "🎉", "❤️", "😢", "😮", "👏", "🚀"]

function EmojiPicker({
  emojis = DEFAULT_EMOJIS,
  onSelect,
  className,
}: {
  emojis?: string[]
  onSelect?: (emoji: string) => void
  className?: string
}) {
  return (
    // Each button's name is the emoji itself; screen readers announce its CLDR name ("grinning face").
    <div
      role="group"
      aria-label="Emoji"
      className={cn(
        // 16 px corners around 8 px buttons with 8 px of air keep the corners concentric.
        "grid grid-cols-6 gap-1 rounded-xl border border-border bg-popover p-2 shadow-lg",
        className
      )}
    >
      {emojis.map((emoji) => (
        <button
          key={emoji}
          type="button"
          onClick={() => onSelect?.(emoji)}
          className="flex size-8 items-center justify-center rounded-md text-lg outline-none hover:bg-bg-page active:bg-bg-subtle focus-ring"
        >
          {emoji}
        </button>
      ))}
    </div>
  )
}

export { EmojiPicker }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
